package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,length=160) private String title; @Column(columnDefinition="TEXT") private String message; @Column(nullable=false) private boolean readFlag=false; private LocalDateTime createdAt; @PrePersist void onCreate(){createdAt=LocalDateTime.now();} public Notification(){} public Notification(User u,String t,String m){user=u;title=t;message=m;} public Long getId(){return id;} public User getUser(){return user;} public String getTitle(){return title;} public String getMessage(){return message;} public boolean isReadFlag(){return readFlag;} public void setReadFlag(boolean v){readFlag=v;} public LocalDateTime getCreatedAt(){return createdAt;} }